import{_ as a,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"5. 使用标头和预处理器","description":"The Little Book of C 中文版 — 5. 使用标头和预处理器","frontmatter":{"title":"5. 使用标头和预处理器","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 5. 使用标头和预处理器","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":5,"sidebarWeight":5,"alternateZh":"/posts/c教程/zh-CN/01-入门/005-Using Headers and the Preprocessor","alternateEn":"/posts/c教程/en-US/01-Getting Started/005-Using Headers and the Preprocessor"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/005-Using Headers and the Preprocessor.md","filePath":"posts/c教程/zh-CN/01-入门/005-Using Headers and the Preprocessor.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/01-入门/005-Using Headers and the Preprocessor.md"};function i(o,s,l,c,d,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<p>[English version](/posts/c教程/en-US/01-Getting Started/005-Using Headers and the Preprocessor)</p><p>每个 C 程序在开始运行之前就开始了，有一个叫做预处理器的东西。在编译器将代码转换为机器指令之前，预处理器会对其进行准备：它提取文件、替换宏并设置程序所需的一切。这一步就是让<code>#include &lt;stdio.h&gt;</code>工作，这是理解大型 C 项目如何组织的关键。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span><span>   // include the standard input/output header</span></span>
<span class="line"><span>#define PI 3.14159</span><span>    // define a constant macro</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;PI is approximately %.2f\\n&quot;, PI);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当您编译该程序时，预处理器将替换<code>PI</code>和<code>3.14159</code>并包括文件的内容<code>stdio.h</code>在编译器启动之前。</p><p>您可以通过运行以下命令查看预处理结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E program.c</span></span></code></pre></div><p>它将输出更长版本的代码，显示所有行<code>stdio.h</code>添加到幕后。</p><h4 id="标题如何工作" tabindex="-1">标题如何工作 <a class="header-anchor" href="#标题如何工作" aria-label="Permalink to &quot;标题如何工作&quot;">​</a></h4><p>标头是声明文件。它们告诉编译器存在什么，例如函数、常量和类型，而不实际提供代码（定义）。例如，<code>stdio.h</code>声明函数<code>printf()</code>所以编译器知道如何调用它。</p><p>包含标头的主要方式有两种：</p><p>系统标头：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span></code></pre></div><p>编译器在标准库目录中查找这些。</p><p>用户定义的标头：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;myutils.h&quot;</span></span></code></pre></div><p>编译器首先在您的项目文件夹中查找这些。</p><p>这种分离使大型程序保持模块化和可读性。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>预处理器就像程序的“设置人员”。它不会运行您的代码，而是准备代码。通过了解标头和宏，您可以：</p><ul><li>将大程序分割成更小的、可重用的部分。</li><li>在一处定义常量而不是重复值。</li><li>编写可在不同系统上编译的可移植代码。</li><li>避免由于缺少声明而导致的细微错误。</li></ul><p>当你写的时候<code>#include &lt;stdio.h&gt;</code>，您正在利用数十年的可靠共享代码，这是 C 生态系统的最大优势之一。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>创建两个文件：</p><p>Mathutils.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATHUTILS_H</span></span>
<span class="line"><span>#define MATHUTILS_H</span></span>
<span class="line"><span>#define SQUARE(x) ((x) * (x))</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;mathutils.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int n = 5;</span></span>
<span class="line"><span>    printf(&quot;The square of %d is %d\\n&quot;, n, SQUARE(n));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o main</span></span>
<span class="line"><span>./main</span></span></code></pre></div><p>尝试编辑宏<code>mathutils.h</code>添加一个<code>CUBE(x)</code>函数，并将其用于<code>main.c</code>.</p><p>然后运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E main.c | less</span></span></code></pre></div><p>探索预处理的代码并查看包含和宏如何扩展。</p><p>一旦掌握了标头和预处理，您就会了解大型 C 代码库如何保持组织性，以及简单的 C 代码库如何保持组织性。<code>#include</code>line 可以解锁整个功能库。</p>`,35)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
